<?php
require_once 'config.php'; require_once 'includes/auth_check.php'; require_once 'includes/notification_helper.php'; require_once 'includes/security.php';
if(($_SESSION['user_role']??'')!=='admin'){http_response_code(403);exit('Administrator access required.');}
$id=(int)($_GET['id']??$_POST['complaint_id']??0);$message='';$error='';$stmt=$conn->prepare('SELECT c.id,c.reference_no,c.subject,c.status,c.department_id,c.officer_id,u.id owner_id FROM complaints c JOIN users u ON u.id=c.user_id WHERE c.id=? LIMIT 1');$stmt->bind_param('i',$id);$stmt->execute();$c=$stmt->get_result()->fetch_assoc();$stmt->close();if(!$c){http_response_code(404);exit('Complaint not found.');}
if($_SERVER['REQUEST_METHOD']==='POST'){try{require_csrf();$reason=trim($_POST['reason']??'');if(strlen($reason)<10)throw new RuntimeException('Provide at least 10 characters explaining the escalation.');$stmt=$conn->prepare('INSERT INTO complaint_escalations (complaint_id,from_user_id,to_user_id,reason,created_by) VALUES (?,?,?,?,?)');$from=(int)($_SESSION['user_id']);$to=$c['officer_id']?((int)$c['officer_id']):null;$stmt->bind_param('iiisi',$id,$from,$to,$reason,$from);$stmt->execute();$stmt->close();$stmt=$conn->prepare("UPDATE complaints SET escalated_at=NOW(), escalation_reason=? WHERE id=?");$stmt->bind_param('si',$reason,$id);$stmt->execute();$stmt->close();create_notification($conn,(int)$c['owner_id'],$id,'Complaint escalated','Your complaint '.$c['reference_no'].' has been escalated for priority review.','system');audit_log($conn,'escalate','complaint',$id,'Complaint escalated: '.$reason);$message='Complaint escalated successfully.';}catch(Throwable $e){$error=$e->getMessage();}}
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Escalate Complaint | Grievance Portal</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"></head><body class="bg-light"><div class="d-flex min-vh-100"><?php include 'includes/sidebar.php';?><main class="flex-grow-1"><header class="bg-white border-bottom p-3"><h4 class="mb-0">Escalate Complaint</h4><small class="text-muted">Create an accountable escalation record for <?=e($c['reference_no'])?>.</small></header><div class="container p-4"><div class="card border-0 shadow-sm" style="max-width:720px"><div class="card-body p-4"><h5><?=e($c['subject'])?></h5><p class="text-muted">Current status: <?=e($c['status'])?></p><?php if($message):?><div class="alert alert-success"><?=e($message)?></div><?php endif;?><?php if($error):?><div class="alert alert-danger"><?=e($error)?></div><?php endif;?><form method="post"><?=csrf_field()?><input type="hidden" name="complaint_id" value="<?=$id?>"><label class="form-label">Reason</label><textarea class="form-control mb-3" name="reason" rows="4" minlength="10" required placeholder="Explain the SLA breach, risk, or management attention required."></textarea><button class="btn btn-danger">Create escalation</button><a class="btn btn-outline-secondary ms-2" href="admin_audit.php">Cancel</a></form></div></div></div></main></div></body></html>
